20		let loading = $state(true);
21		let error = $state('');
22	
23		// Email management state
24		let isAddingEmail = $state(false);
25		let newEmailInput = $state('');
26		let editingIndex: number | null = $state(null);
27		let editEmailInput = $state('');
28		let deletingEmail: { index: number; email: string } | null = $state(null);
29		let savingEmail = $state(false);
