32		onMount(() => {
33			// Subscribe to auth state changes synchronously so onMount can return a
34			// synchronous cleanup (an async onMount callback can't return a teardown).
35			const { data: subscription } = supabase.auth.onAuthStateChange(async (_event, newSession) => {
36				session = newSession;
37				if (newSession) {
38					await loadProfile();
39				} else {
40					profile = null;
41				}
42			});
43	
44			// Initial session load (#{#upp1a})
45			void (async () => {
46				const { data } = await supabase.auth.getSession();
47				session = data.session;
48				if (session) {
49					await loadProfile();
50				}
51				loading = false;
52			})();
53	
54			return () => {
55				subscription.subscription.unsubscribe();
56			};
57		});
58	
59		async function loadProfile() {
60			if (!session?.user?.id) return;
61	
62			const { data, error: err } = await supabase
63				.from('profiles')
64				.select('*')
65				.eq('user_id', session.user.id)
66				.single();
67	
68			if (err) {
69				// If no profile exists yet, that's okay - user can still add emails
70				if (err.code !== 'PGRST116') {
71					console.error('Error loading profile:', err);
72					error = 'Failed to load profile data';
73				}
74			} else {
75				profile = data;
76			}
77		}
78	
79		// Extract user info from session (#{#upp2b})
80		let userEmail = $derived(session?.user?.email || '');
81		let userId = $derived(session?.user?.id || '');
82		let createdAt = $derived(
83			session?.user?.created_at ? new Date(session.user.created_at).toLocaleDateString() : ''
84		);
85	
86		// Extract additional emails from profile (#{#upp4a})
87		let additionalEmails = $derived(
88			profile
89				? ([
90						profile.email_1,
91						profile.email_2,
92						profile.email_3,
93						profile.email_4,
94						profile.email_5
95					].filter((email) => email !== null && email !== '') as string[])
96				: []
97		);
98	
99		// Add email functionality (#{#upp4b})
100		function startAddingEmail() {
101			isAddingEmail = true;
102			newEmailInput = '';
103			error = '';
104		}
105	
106		function cancelAddingEmail() {
107			isAddingEmail = false;
108			newEmailInput = '';
109			error = '';
110		}
111	
112		async function saveNewEmail() {
113			if (!session?.user?.id) return;
114	
115			// Validate email format (#{#upp4b})
116			const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
117			if (!emailRegex.test(newEmailInput.trim())) {
118				error = 'Please enter a valid email address';
119				return;
120			}
121	
122			// Check for duplicates (case-insensitive)
123			const normalizedNew = newEmailInput.trim().toLowerCase();
124			const existingEmails = [
125				userEmail.toLowerCase(),
126				...additionalEmails.map((e) => e.toLowerCase())
127			];
128	
129			if (existingEmails.includes(normalizedNew)) {
130				error = 'This email address is already in your profile';
131				return;
132			}
133	
134			savingEmail = true;
135			error = '';
136	
137			try {
138				// Find first available email slot
139				const emailSlots = ['email_1', 'email_2', 'email_3', 'email_4', 'email_5'];
140				const usedSlots = profile
141					? [profile.email_1, profile.email_2, profile.email_3, profile.email_4, profile.email_5]
142					: [null, null, null, null, null];
143	
144				const firstAvailableIndex = usedSlots.findIndex((slot) => !slot);
145	
146				if (firstAvailableIndex === -1) {
147					error = 'All email slots are full';
148					savingEmail = false;
149					return;
150				}
151	
152				const columnToUpdate = emailSlots[firstAvailableIndex];
153	
154				// Create or update profile record
155				if (!profile) {
156					// Create new profile record
157					const { error: insertErr } = await supabase.from('profiles').insert({
158						user_id: session.user.id,
159						[columnToUpdate]: newEmailInput.trim()
160					});
161	
162					if (insertErr) {
163						console.error('Error creating profile:', insertErr);
164						error = 'Failed to add email address';
165					} else {
166						await loadProfile();
167						isAddingEmail = false;
168						newEmailInput = '';
169					}
170				} else {
171					// Update existing profile record
172					const { error: updateErr } = await supabase
173						.from('profiles')
174						.update({ [columnToUpdate]: newEmailInput.trim() })
175						.eq('user_id', session.user.id);
176	
177					if (updateErr) {
178						console.error('Error updating profile:', updateErr);
179						error = 'Failed to add email address';
180					} else {
181						await loadProfile();
182						isAddingEmail = false;
183						newEmailInput = '';
184					}
185				}
186			} finally {
187				savingEmail = false;
188			}
189		}
190	
191		// Edit email functionality (#{#upp4c})
192		function startEditingEmail(index: number, currentEmail: string) {
193			editingIndex = index;
194			editEmailInput = currentEmail;
195			error = '';
196		}
197	
198		function cancelEditingEmail() {
199			editingIndex = null;
200			editEmailInput = '';
201			error = '';
202		}
203	
204		async function saveEditedEmail() {
205			if (!session?.user?.id || editingIndex === null || !profile) return;
206	
207			// Validate email format (#{#upp4c})
208			const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
209			if (!emailRegex.test(editEmailInput.trim())) {
210				error = 'Please enter a valid email address';
211				return;
212			}
213	
214			// Check for duplicates (case-insensitive), excluding current email
215			const normalizedNew = editEmailInput.trim().toLowerCase();
216			const currentEmails = [
217				userEmail.toLowerCase(),
218				...additionalEmails.map((e, idx) => (idx === editingIndex ? null : e.toLowerCase()))
219			].filter((e) => e !== null);
220	
221			if (currentEmails.includes(normalizedNew)) {
222				error = 'This email address is already in your profile';
223				return;
224			}
225	
226			savingEmail = true;
227			error = '';
228	
229			try {
230				// Map index to column name
231				const emailSlots = ['email_1', 'email_2', 'email_3', 'email_4', 'email_5'];
232	
233				// Find which actual column contains the email at this display index
234				const profileEmails = [
235					profile.email_1,
236					profile.email_2,
237					profile.email_3,
238					profile.email_4,
239					profile.email_5
240				];
241	
242				// Find the column index by matching the current email value
243				const originalEmail = additionalEmails[editingIndex];
244				const columnIndex = profileEmails.findIndex((e) => e === originalEmail);
245	
246				if (columnIndex === -1) {
247					error = 'Email not found in profile';
248					savingEmail = false;
249					return;
250				}
251	
252				const columnToUpdate = emailSlots[columnIndex];
253	
254				const { error: updateErr } = await supabase
255					.from('profiles')
256					.update({ [columnToUpdate]: editEmailInput.trim() })
257					.eq('user_id', session.user.id);
258	
259				if (updateErr) {
260					console.error('Error updating email:', updateErr);
261					error = 'Failed to update email address';
262				} else {
263					await loadProfile();
264					editingIndex = null;
265					editEmailInput = '';
266				}
267			} finally {
268				savingEmail = false;
269			}
270		}
271	
272		// Delete email functionality (#{#upp4d})
273		function confirmDeleteEmail(index: number, email: string) {
274			deletingEmail = { index, email };
275			error = '';
276		}
277	
278		function cancelDeleteEmail() {
279			deletingEmail = null;
280		}
281	
282		async function deleteEmail() {
283			if (!session?.user?.id || deletingEmail === null || !profile) return;
284	
285			deletingInProgress = true;
286			error = '';
287	
288			try {
289				const { index, email } = deletingEmail;
290	
291				// Find which column contains this email
292				const profileEmails = [
293					profile.email_1,
294					profile.email_2,
295					profile.email_3,
296					profile.email_4,
297					profile.email_5
298				];
299	
300				const columnIndex = profileEmails.findIndex((e) => e === email);
301	
302				if (columnIndex === -1) {
303					error = 'Email not found in profile';
304					deletingInProgress = false;
305					return;
306				}
307	
308				const emailSlots = ['email_1', 'email_2', 'email_3', 'email_4', 'email_5'];
309				const columnToUpdate = emailSlots[columnIndex];
310	
311				// Set column to NULL (#{#upp4d})
312				const { error: updateErr } = await supabase
313					.from('profiles')
314					.update({ [columnToUpdate]: null })
315					.eq('user_id', session.user.id);
316	
317				if (updateErr) {
318					console.error('Error deleting email:', updateErr);
319					error = 'Failed to delete email address';
320				} else {
321					await loadProfile();
322					deletingEmail = null;
323				}
324			} finally {
325				deletingInProgress = false;
326			}
327		}
328	</script>
