62	
63			it('should import Supabase client for authentication', () => {
64				const routePath = join(process.cwd(), 'src/routes/profile/+page.svelte');
65	
66				if (!existsSync(routePath)) {
67					expect.fail('Route file does not exist');
68					return;
69				}
70	
71				const content = readFileSync(routePath, 'utf-8');
72	
73				// Check for Supabase imports
74				const hasSupabaseImport =
75					content.includes("from '$lib/supabaseClient'") || content.includes('supabaseClient');
76	
77				expect(hasSupabaseImport).toBe(true);
78			});
79	
80			it('should handle loading state', () => {
81				const routePath = join(process.cwd(), 'src/routes/profile/+page.svelte');
82	
83				if (!existsSync(routePath)) {
84					expect.fail('Route file does not exist');
85					return;
86				}
87	
88				const content = readFileSync(routePath, 'utf-8');
89	
90				// Check for loading state variable and UI
91				const hasLoadingState =
92					(content.includes('let loading') || content.includes('loading =')) &&
93					(content.includes('Loading profile') || content.includes('loading'));
94	
95				expect(hasLoadingState).toBe(true);
96			});
97	
98			it('should fetch user session on mount', () => {
99				const routePath = join(process.cwd(), 'src/routes/profile/+page.svelte');
100	
101				if (!existsSync(routePath)) {
102					expect.fail('Route file does not exist');
103					return;
104				}
105	
106				const content = readFileSync(routePath, 'utf-8');
107	
108				// Check for onMount and getSession
109				const hasSessionFetch =
110					content.includes('onMount') &&
111					(content.includes('getSession') || content.includes('auth.getSession'));
112	
113				expect(hasSessionFetch).toBe(true);
114			});
115	
116			it('should fetch profile data from profiles table', () => {
117				const routePath = join(process.cwd(), 'src/routes/profile/+page.svelte');
118	
119				if (!existsSync(routePath)) {
120					expect.fail('Route file does not exist');
121					return;
122				}
123	
124				const content = readFileSync(routePath, 'utf-8');
125	
126				// Check for profile table query
127				const hasProfileQuery =
128					content.includes("from('profiles')") || content.includes('.from("profiles")');
129	
130				expect(hasProfileQuery).toBe(true);
131			});
132	
133			it('should handle unauthenticated users gracefully', () => {
134				const routePath = join(process.cwd(), 'src/routes/profile/+page.svelte');
135	
136				if (!existsSync(routePath)) {
137					expect.fail('Route file does not exist');
138					return;
139				}
140	
141				const content = readFileSync(routePath, 'utf-8');
142	
143				// Check for session null handling or login prompt
144				const hasUnauthHandling =
145					(content.includes('log in') || content.includes('login')) &&
146					(content.includes('if session') || content.includes('if $session'));
