7	export function toDate(isoString: string | null | undefined): Date | undefined {
8		if (!isoString) return undefined;
9		const parts = isoString.split('-');
10		if (parts.length !== 3) return undefined;
11		const year = parseInt(parts[0], 10);
12		const month = parseInt(parts[1], 10);
13		const day = parseInt(parts[2], 10);
14		if (isNaN(year) || isNaN(month) || isNaN(day)) return undefined;
15		return new Date(year, month - 1, day);
16	}
