18	/**
19	 * Formats a YYYY-MM-DD date string for display (e.g., "Mar 1, 2026").
20	 * Parses date parts manually to avoid timezone shift from new Date(string).
21	 */
22	export function formatDate(
23		isoString: string | null | undefined,
24		options: Intl.DateTimeFormatOptions = { year: 'numeric', month: 'short', day: 'numeric' }
25	): string {
26		if (!isoString) return '—';
27		const date = toDate(isoString);
28		if (!date) return '—';
29		return date.toLocaleDateString('en-US', options);
