/**
 * Pure helpers for managing a user's additional email addresses on the profile page.
 *
 * A profile stores up to five additional emails in fixed columns `email_1` … `email_5`.
 * Slots are never shifted: adding fills the first empty slot, deleting sets a slot to NULL.
 * These functions are extracted verbatim from `src/routes/profile/+page.svelte` so the
 * page logic can be unit tested without a Supabase client.
 */

/** The five profile columns that hold additional email addresses, in slot order. */
export const EMAIL_SLOT_COLUMNS = [
	'email_1',
	'email_2',
	'email_3',
	'email_4',
	'email_5'
] as const;

export type EmailSlotColumn = (typeof EMAIL_SLOT_COLUMNS)[number];

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/**
 * Returns true when the trimmed input looks like a valid email address.
 * Matches the page's `emailRegex.test(input.trim())` check.
 */
export function isValidEmail(email: string): boolean {
	return EMAIL_REGEX.test(email.trim());
}

/**
 * Case-insensitive duplicate check. The candidate is trimmed and lower-cased, then
 * compared against the lower-cased `existing` list (which should already include the
 * primary email when guarding against duplicates on the profile page).
 */
export function isDuplicateEmail(candidate: string, existing: string[]): boolean {
	const normalized = candidate.trim().toLowerCase();
	return existing.some((email) => email.toLowerCase() === normalized);
}

/**
 * Index of the first empty slot (null or empty string), or null when all slots are full.
 * Mirrors the page's `findIndex((slot) => !slot)` behavior.
 */
export function firstAvailableSlot(slots: (string | null)[]): number | null {
	const index = slots.findIndex((slot) => !slot);
	return index === -1 ? null : index;
}

/**
 * Index of the slot whose value exactly matches `email`, or null when not found.
 * Used to map a display-row email back to its underlying `email_N` column for
 * edit and delete operations.
 */
export function slotIndexOfEmail(slots: (string | null)[], email: string): number | null {
	const index = slots.findIndex((slot) => slot === email);
	return index === -1 ? null : index;
}

/**
 * The `email_N` column name for a given zero-based slot index, or null when out of range.
 */
export function slotColumn(index: number): EmailSlotColumn | null {
	return EMAIL_SLOT_COLUMNS[index] ?? null;
}

