import { describe, it, expect } from 'vitest';
import {
	EMAIL_SLOT_COLUMNS,
	isValidEmail,
	isDuplicateEmail,
	firstAvailableSlot,
	slotIndexOfEmail,
	slotColumn
} from './profileEmails';

describe('isValidEmail', () => {
	it('accepts a normal address', () => {
		expect(isValidEmail('user@example.com')).toBe(true);
	});

	it('accepts subdomains and plus-addressing', () => {
		expect(isValidEmail('first.last+tag@mail.example.co.uk')).toBe(true);
	});

	it('trims surrounding whitespace before validating', () => {
		expect(isValidEmail('  user@example.com  ')).toBe(true);
	});

	it('rejects an empty string', () => {
		expect(isValidEmail('')).toBe(false);
	});

	it('rejects a whitespace-only string', () => {
		expect(isValidEmail('   ')).toBe(false);
	});

	it('rejects a value with no @', () => {
		expect(isValidEmail('userexample.com')).toBe(false);
	});

	it('rejects a value with no domain dot', () => {
		expect(isValidEmail('user@example')).toBe(false);
	});

	it('rejects a value with no local part', () => {
		expect(isValidEmail('@example.com')).toBe(false);
	});

	it('rejects a value with internal whitespace', () => {
		expect(isValidEmail('user name@example.com')).toBe(false);
	});

	it('rejects a value with two @ signs', () => {
		expect(isValidEmail('a@b@example.com')).toBe(false);
	});
});

describe('isDuplicateEmail', () => {
	const existing = ['primary@example.com', 'work@example.com'];

	it('detects an exact match', () => {
		expect(isDuplicateEmail('work@example.com', existing)).toBe(true);
	});

	it('is case-insensitive on the candidate', () => {
		expect(isDuplicateEmail('WORK@Example.com', existing)).toBe(true);
	});

	it('is case-insensitive on the existing list', () => {
		expect(isDuplicateEmail('work@example.com', ['WORK@EXAMPLE.COM'])).toBe(true);
	});

	it('trims the candidate before comparing', () => {
		expect(isDuplicateEmail('  work@example.com  ', existing)).toBe(true);
	});

	it('matches against the primary email in the list', () => {
		expect(isDuplicateEmail('PRIMARY@example.com', existing)).toBe(true);
	});

	it('returns false for a genuinely new address', () => {
		expect(isDuplicateEmail('new@example.com', existing)).toBe(false);
	});

	it('returns false against an empty list', () => {
		expect(isDuplicateEmail('anything@example.com', [])).toBe(false);
	});
});

describe('firstAvailableSlot', () => {
	it('returns 0 when all slots are empty', () => {
		expect(firstAvailableSlot([null, null, null, null, null])).toBe(0);
	});

	it('returns the first empty index when some slots are full', () => {
		expect(firstAvailableSlot(['a@x.com', 'b@x.com', null, null, null])).toBe(2);
	});

	it('skips leading full slots and finds a later gap', () => {
		expect(firstAvailableSlot(['a@x.com', null, 'c@x.com', null, null])).toBe(1);
	});

	it('treats an empty string as an available slot', () => {
		expect(firstAvailableSlot(['a@x.com', '', null, null, null])).toBe(1);
	});

	it('returns null when every slot is full', () => {
		expect(
			firstAvailableSlot(['a@x.com', 'b@x.com', 'c@x.com', 'd@x.com', 'e@x.com'])
		).toBe(null);
	});
});

describe('slotIndexOfEmail', () => {
	const slots = ['a@x.com', null, 'c@x.com', null, 'e@x.com'];

	it('finds the slot index of a matching email', () => {
		expect(slotIndexOfEmail(slots, 'c@x.com')).toBe(2);
	});

	it('finds an email in the first slot', () => {
		expect(slotIndexOfEmail(slots, 'a@x.com')).toBe(0);
	});

	it('finds an email in the last slot', () => {
		expect(slotIndexOfEmail(slots, 'e@x.com')).toBe(4);
	});

	it('returns null when the email is not present', () => {
		expect(slotIndexOfEmail(slots, 'missing@x.com')).toBe(null);
	});

	it('is case-sensitive (exact value match)', () => {
		expect(slotIndexOfEmail(slots, 'A@X.COM')).toBe(null);
	});
});

describe('slotColumn', () => {
	it('maps each valid index to its email_N column', () => {
		expect(slotColumn(0)).toBe('email_1');
		expect(slotColumn(1)).toBe('email_2');
		expect(slotColumn(2)).toBe('email_3');
		expect(slotColumn(3)).toBe('email_4');
		expect(slotColumn(4)).toBe('email_5');
	});

	it('returns null for an out-of-range index', () => {
		expect(slotColumn(5)).toBe(null);
		expect(slotColumn(-1)).toBe(null);
	});

	it('exposes the five columns in order', () => {
		expect(EMAIL_SLOT_COLUMNS).toEqual([
			'email_1',
			'email_2',
			'email_3',
			'email_4',
			'email_5'
		]);
	});
});

describe('add and delete column mapping (page behaviour)', () => {
	it('adds into the first available column and never shifts on delete', () => {
		// Two emails in email_1 and email_2; delete email_1 leaves a gap (no shift).
		const afterDelete: (string | null)[] = [null, 'b@x.com', null, null, null];

		// The remaining email stays in its original column.
		expect(slotIndexOfEmail(afterDelete, 'b@x.com')).toBe(1);
		expect(slotColumn(slotIndexOfEmail(afterDelete, 'b@x.com') ?? -1)).toBe('email_2');

		// Adding a new email fills the first gap (email_1), not the end.
		const nextIndex = firstAvailableSlot(afterDelete);
		expect(nextIndex).toBe(0);
		expect(slotColumn(nextIndex ?? -1)).toBe('email_1');
	});

	it('reports full when all five columns are occupied', () => {
		const full = ['a@x.com', 'b@x.com', 'c@x.com', 'd@x.com', 'e@x.com'];
		expect(firstAvailableSlot(full)).toBe(null);
	});
});

